// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "contacts_sheet": "Contacts",
  "graph_api_base": "https://graph.facebook.com/v25.0",
  "phone_number_id": "REPLACE_WITH_PHONE_NUMBER_ID",
  "team_chat_id": "REPLACE_WITH_TEAM_CHAT_ID",
  "handoff_hours": 12
} }];

// Bridge — a manager answers a WhatsApp client from the Telegram team chat, takes the client, or gives them back to the bot.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Contacts sheet: one row per WhatsApp number. The sheet may start empty: the header is written with the first contact.
const CCOLS = ['wa_id', 'name', 'phone', 'first_seen', 'last_in_at', 'last_out_at', 'status', 'stage', 'need', 'budget', 'timeline', 'details',
  'hot', 'handoff_until', 'followup_sent', 'history', 'manager', 'notes'];
const colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const CLAST = colLetter(CCOLS.length - 1);
const contactsRange = () => `${quoteSheet(cfg.contacts_sheet)}!A1:${CLAST}`;
const contactRow = (row) => `${quoteSheet(cfg.contacts_sheet)}!A${row}:${CLAST}${row}`;
const waBatchUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(contactsRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.catalog_sheet)}!A1:C`)}`;
const contactsTable = (values) => { const rows = values || []; const header = rows.length && rows[0][0] === 'wa_id'; return { header, rows: header ? rows.slice(1) : [] }; };
const ccell = (row, c) => row[CCOLS.indexOf(c)] || '';
const contactObject = (row) => Object.fromEntries(CCOLS.map((c) => [c, ccell(row, c)]));
const graphUrl = () => `${cfg.graph_api_base}/${encodeURIComponent(cfg.phone_number_id)}/messages`;
const waText = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: String(body).slice(0, 4000) } });
const update = $('Telegram Trigger').first().json;
const table = contactsTable($input.first().json.values);
const now = nowMs();
const iso = new Date(now).toISOString();
const team = String(cfg.team_chat_id);
const out = (json) => [{ json: Object.assign({ act: false, send: false, write: false, note: '', callback_id: '', team_chat: cfg.team_chat_id, graph_url: graphUrl() }, json) }];

let action = '', waId = '', text = '', who = '', callbackId = '';
const cb = update.callback_query;
if (cb) {
  if (String(cb.message && cb.message.chat && cb.message.chat.id) !== team) return out({});
  [action, waId] = String(cb.data || '').split(':');
  who = [cb.from.first_name, cb.from.last_name].filter(Boolean).join(' ') || cb.from.username || '';
  callbackId = cb.id;
} else if (update.message && String(update.message.chat.id) === team && update.message.text) {
  const quoted = (update.message.reply_to_message || {}).text || '';
  const ref = /WA: (\d{6,15})/.exec(quoted);
  if (!ref) return out({});
  action = 'reply'; waId = ref[1]; text = update.message.text.slice(0, 4000);
  who = [update.message.from.first_name, update.message.from.last_name].filter(Boolean).join(' ');
} else return out({});
if (!['reply', 'take', 'bot'].includes(action) || !waId) return out({});

const index = table.rows.findIndex((r) => ccell(r, 'wa_id') === waId);
if (index < 0) return out({ act: true, note: `Клиент +${waId} не найден в таблице`, callback_id: callbackId });
const c = contactObject(table.rows[index]);
const write = (extra) => ({ write: true, http: { method: 'PUT', url: sheetUrl(encodeURIComponent(contactRow(index + (table.header ? 2 : 1)))) + '?valueInputOption=RAW', body: { values: [CCOLS.map((k) => String(c[k] || ''))] } }, ...extra });

if (action === 'bot') {
  c.status = 'bot'; c.handoff_until = '';
  return out(Object.assign({ act: true, note: `Клиент +${waId} снова с ботом`, callback_id: callbackId }, write({})));
}
c.status = 'manager';
c.manager = who || c.manager;
c.handoff_until = new Date(now + (cfg.handoff_hours || 12) * 60 * MIN).toISOString();
if (action === 'take') return out(Object.assign({ act: true, note: `${who || 'Менеджер'} ведёт клиента +${waId}. Бот молчит ${cfg.handoff_hours || 12} ч.`, callback_id: callbackId }, write({})));

// WhatsApp allows free-form messages only within 24 hours of the client's last message.
const lastIn = Date.parse(c.last_in_at);
if (isNaN(lastIn) || now - lastIn > 24 * 60 * MIN) {
  return out({ act: true, note: `Не отправлено: с последнего сообщения клиента прошло больше 24 часов. WhatsApp разрешает только одобренный шаблон — напишите клиенту из инструмента рассылок или позвоните: +${waId}.` });
}
c.last_out_at = iso;
c.history = `${c.history ? c.history + '\n' : ''}${localText(now)} · ${who || 'менеджер'}: ${text.replace(/\n+/g, ' ').slice(0, 400)}`.slice(-3500);
return out(Object.assign({ act: true, send: true, message: waText(waId, text), note: `Отправлено в WhatsApp: +${waId}` }, write({})));

// Not Delivered — WhatsApp refused the message (most often: more than 24 hours since the client wrote). A person must act.
const sent = $('Bridge').first().json;
const error = $input.first().json.error || $input.first().json;
const raw = JSON.stringify(error);
const window = /131047|re-engagement/i.test(raw);
return [{ json: { text: [
  'Сообщение в WhatsApp не доставлено',
  `Клиент: +${sent.wa_id || (sent.message || {}).to || '—'}`,
  window ? 'Причина: прошло больше 24 часов с последнего сообщения клиента — WhatsApp разрешает только одобренный шаблон.' : `Ошибка: ${raw.slice(0, 300)}`,
  `Текст: ${(((sent.message || {}).text || {}).body || ((((sent.message || {}).interactive || {}).body) || {}).text || '').slice(0, 600)}`,
].join('\n') } }];
